INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2016, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2016): ||263\_IRBR\_DIPL\_1F\_001\_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016 PROVA OBJETIVA – PRIMEIRA FASE – PRIMEIRA ETAPA LÍNGUA PORTUGUESA “Ah, o Brasil, que país\!”, exclama uma personagem de La Vie Dangereuse. “Que país, esse Brasil\!”, repetirão, com diferentes entonações, o melancólico capitão de longo curso, um agente da Terceira Internacional, a mulher de um diplomata refo | O trecho “paisagem deveras anônima” (R. 64 e 65), que apresenta expressão atribuída a Gobineau, faz referência a um lugar novo e ainda desconhecido, tendo sentido similar ao do trecho “um mundo inteiramente inédito” (R. 63 e 64). 2 Segundo o autor do texto, Blaise Cendrars foi instigado a viajar ao Brasil devido à existência, no país, de ritmos musicais exóticos, entre os quais o maxixe. 3 Darius Milhaud, compositor que exerceu funções diplomáticas no Rio de Janeiro, inspirou-se na música popular carioca para compor o Boeuf sur le Toît. 4 Porquanto, conforme o texto, Blai', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Português', 'Interpretação de texto', 'Item 2 (TPS 2016): ||263\_IRBR\_DIPL\_1F\_001\_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016 PROVA OBJETIVA – PRIMEIRA FASE – PRIMEIRA ETAPA LÍNGUA PORTUGUESA “Ah, o Brasil, que país\!”, exclama uma personagem de La Vie Dangereuse. “Que país, esse Brasil\!”, repetirão, com diferentes entonações, o melancólico capitão de longo curso, um agente da Terceira Internacional, a mulher de um diplomata refo | A autora considera que o romance Maíra é uma incursão do romancista e antropólogo Darcy Ribeiro pelo épico e opina que um “narrador coletivo índio” (R.44) é responsável pelos melhores trechos da mencionada obra literária.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2016, 'Português', 'Interpretação de texto', 'Item 3 (TPS 2016): ||263\_IRBR\_DIPL\_1F\_001\_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016 PROVA OBJETIVA – PRIMEIRA FASE – PRIMEIRA ETAPA LÍNGUA PORTUGUESA “Ah, o Brasil, que país\!”, exclama uma personagem de La Vie Dangereuse. “Que país, esse Brasil\!”, repetirão, com diferentes entonações, o melancólico capitão de longo curso, um agente da Terceira Internacional, a mulher de um diplomata refo | Conforme o texto, iñaron é palavra tupi que não é apropriada para denotar o sofrimento de todas as tribos indígenas, mas poderia denotar os sentimentos de fúria de heróis gregos como Agave e Aquiles.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2016, 'Português', 'Interpretação de texto', 'Item 4 (TPS 2016): ||263\_IRBR\_DIPL\_1F\_001\_01N569592|| CESPE | CEBRASPE – IRBr Diplomata – Aplicação: 2016 PROVA OBJETIVA – PRIMEIRA FASE – PRIMEIRA ETAPA LÍNGUA PORTUGUESA “Ah, o Brasil, que país\!”, exclama uma personagem de La Vie Dangereuse. “Que país, esse Brasil\!”, repetirão, com diferentes entonações, o melancólico capitão de longo curso, um agente da Terceira Internacional, a mulher de um diplomata refo | Ao comparar a representação do índio na literatura brasileira com a do índio na literatura hispano-americana, a autora conclui que romances com percepção antropológica costumam ser mais raros e tendem a incursionar pelo épico. QUESTÃO 5 Julgue (C ou E) os itens seguintes, relacionados às ideias desenvolvidas no texto II. conflitos e tensões que transcendem o Brasil ou o espaço hispano-americano. autora do texto evidencia o confronto entre o “capitalismo selvagem no país” (R. 33 e 34) e a cultura indígena. enredos marcados pelas dificuldades enfrentadas por tribos indígena', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
